import{_ as t,o as s,c as n,a4 as a}from"./chunks/framework.BHRp8ZZT.js";const f=JSON.parse('{"title":"Kit de Ressources de Conception de Systèmes","description":"","frontmatter":{},"headers":[],"relativePath":"fr/01_Read_Me.md","filePath":"fr/01_Read_Me.md","lastUpdated":1788996924000}'),l={name:"fr/01_Read_Me.md"};function r(i,e,d,o,c,u){return s(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="kit-de-ressources-de-conception-de-systemes" tabindex="-1">Kit de Ressources de Conception de Systèmes <a class="header-anchor" href="#kit-de-ressources-de-conception-de-systemes" aria-label="Permalink to &quot;Kit de Ressources de Conception de Systèmes&quot;">​</a></h1><blockquote><p><strong>Des Composants de Base aux Cas Pratiques | Conception Haut Niveau (HLD) et Bas Niveau (LLD)</strong></p></blockquote><hr><h2 id="📌-qu-est-ce-que-c-est" tabindex="-1">📌 Qu&#39;est-ce que c&#39;est ? <a class="header-anchor" href="#📌-qu-est-ce-que-c-est" aria-label="Permalink to &quot;📌 Qu&#39;est-ce que c&#39;est ?&quot;">​</a></h2><p>Tout ce qui est nécessaire pour réussir les entretiens de conception de systèmes : fondamentaux théoriques, 42 composants d&#39;architecture, 36 études de cas résolues, blogs d&#39;ingénierie d&#39;entreprises de premier plan, conception bas niveau orientée objet (LLD) et les questions réelles posées par les recruteurs.</p><hr><h2 id="🧭-comment-l-utiliser-efficacement" tabindex="-1">🧭 Comment l&#39;utiliser efficacement <a class="header-anchor" href="#🧭-comment-l-utiliser-efficacement" aria-label="Permalink to &quot;🧭 Comment l&#39;utiliser efficacement&quot;">​</a></h2><ol><li><p>Consultez d&#39;abord la Feuille de route (Roadmap). Elle ordonne 52 semaines, des prérequis à la préparation par entreprise.</p></li><li><p>Maîtrisez les Composants fondamentaux avant d&#39;aborder des études de cas. Vous ne pouvez concevoir avec des composants que vous ignorez.</p></li><li><p>Les Études de cas constituent le cœur. Chacune précise les points à clarifier, les composants, les vrais goulets et les relances.</p></li><li><p>Tentez chaque problème sur feuille blanche AVANT de lire la solution. Lire passivement donne une fausse impression d&#39;apprentissage.</p></li><li><p>Les Blogs d&#39;ingénierie distinguent une réponse scolaire d&#39;une réponse crédible. Lisez deux articles par semaine.</p></li><li><p>La Banque de questions et les Entreprises servent pour l&#39;étape finale en précisant les paliers de recrutement.</p></li></ol><hr><h2 id="💡-conseils-sinceres-d-architectes-seniors" tabindex="-1">💡 Conseils Sincères d&#39;Architectes Seniors <a class="header-anchor" href="#💡-conseils-sinceres-d-architectes-seniors" aria-label="Permalink to &quot;💡 Conseils Sincères d&#39;Architectes Seniors&quot;">​</a></h2><ul><li>Il n&#39;y a pas de conception parfaite unique ; seules comptent les conceptions justifiées.</li><li>La structure prime sur l&#39;accumulation : exigences, calculs, vue d&#39;ensemble, analyse approfondie et compromis.</li><li>Dites ce qui casse. Chaque boîte peut défaillir. Ceux qui anticipent les scénarios de panne sans y être invités marquent des points décisifs.</li><li>Évitez la sur-ingénierie. Introduire Kafka et des microservices pour un problème nécessitant un seul serveur est une faute.</li><li>La conception bas niveau (LLD) n&#39;est pas optionnelle. Des entreprises comme Amazon testent directement la modélisation objet.</li></ul><hr><h2 id="👤-auteur-et-credits" tabindex="-1">👤 Auteur et Crédits <a class="header-anchor" href="#👤-auteur-et-credits" aria-label="Permalink to &quot;👤 Auteur et Crédits&quot;">​</a></h2><ul><li><strong>Fondateur</strong>: Avinash Singh (<a href="https://www.lets-code.co.in" target="_blank" rel="noreferrer">Let&#39;s Code</a>)</li><li><strong>Twitter / X</strong>: <a href="https://x.com/AvinashSingh_20" target="_blank" rel="noreferrer">@AvinashSingh_20</a></li></ul><hr><h2 id="🏷️-niveaux-d-exigence" tabindex="-1">🏷️ Niveaux d&#39;Exigence <a class="header-anchor" href="#🏷️-niveaux-d-exigence" aria-label="Permalink to &quot;🏷️ Niveaux d&#39;Exigence&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Niveau</th><th style="text-align:left;">Définition</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Foundation</strong></td><td style="text-align:left;">Indispensable, socle pour tout ingénieur</td></tr><tr><td style="text-align:left;"><strong>Core</strong></td><td style="text-align:left;">Attendu lors de tout entretien de conception</td></tr><tr><td style="text-align:left;"><strong>Advanced</strong></td><td style="text-align:left;">Facteur clé pour les niveaux Senior et Staff</td></tr></tbody></table><hr><h2 id="📑-table-des-matieres" tabindex="-1">📑 Table des Matières <a class="header-anchor" href="#📑-table-des-matieres" aria-label="Permalink to &quot;📑 Table des Matières&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">Module</th><th style="text-align:left;">Contenu</th><th style="text-align:center;">Entrées</th><th style="text-align:left;">Lien</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong><a href="./02_Skills_Matrix">Skills Matrix</a></strong></td><td style="text-align:left;">Concepts clés, pertinence et évaluation en entretien</td><td style="text-align:center;">99</td><td style="text-align:left;"><a href="./02_Skills_Matrix"><code>02_Skills_Matrix.md</code></a></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong><a href="./03_Roadmap">Roadmap</a></strong></td><td style="text-align:left;">Plan en 52 semaines des fondamentaux aux entretiens</td><td style="text-align:center;">14</td><td style="text-align:left;"><a href="./03_Roadmap"><code>03_Roadmap.md</code></a></td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong><a href="./04_Case_Studies">Case Studies</a></strong></td><td style="text-align:left;">36 problèmes : clarification, composants, goulets clés</td><td style="text-align:center;">36</td><td style="text-align:left;"><a href="./04_Case_Studies"><code>04_Case_Studies.md</code></a></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong><a href="./05_Building_Blocks">Building Blocks</a></strong></td><td style="text-align:left;">Composants : rôles, quand les utiliser et pièges</td><td style="text-align:center;">42</td><td style="text-align:left;"><a href="./05_Building_Blocks"><code>05_Building_Blocks.md</code></a></td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong><a href="./06_Engineering_Blogs">Engineering Blogs</a></strong></td><td style="text-align:left;">Comment les géants construisent leurs architectures réelles</td><td style="text-align:center;">35</td><td style="text-align:left;"><a href="./06_Engineering_Blogs"><code>06_Engineering_Blogs.md</code></a></td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong><a href="./07_Free_Courses">Free Courses</a></strong></td><td style="text-align:left;">Cours gratuits, architectures de référence et cursus</td><td style="text-align:center;">46</td><td style="text-align:left;"><a href="./07_Free_Courses"><code>07_Free_Courses.md</code></a></td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong><a href="./08_YouTube">YouTube</a></strong></td><td style="text-align:left;">Playlists directes avec les meilleurs formateurs</td><td style="text-align:center;">36</td><td style="text-align:left;"><a href="./08_YouTube"><code>08_YouTube.md</code></a></td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong><a href="./09_GitHub_Resources">GitHub Resources</a></strong></td><td style="text-align:left;">Index sélectionnés, fiches et dépôts LLD</td><td style="text-align:center;">35</td><td style="text-align:left;"><a href="./09_GitHub_Resources"><code>09_GitHub_Resources.md</code></a></td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;"><strong><a href="./10_Books_and_Docs">Books &amp; Docs</a></strong></td><td style="text-align:left;">Ouvrages majeurs (DDIA, Alex Xu), papiers et lettres</td><td style="text-align:center;">37</td><td style="text-align:left;"><a href="./10_Books_and_Docs"><code>10_Books_and_Docs.md</code></a></td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;"><strong><a href="./11_Interview_Prep">Interview Prep</a></strong></td><td style="text-align:left;">Questions réelles et intentions d&#39;évaluation sous-jacentes</td><td style="text-align:center;">67</td><td style="text-align:left;"><a href="./11_Interview_Prep"><code>11_Interview_Prep.md</code></a></td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;"><strong><a href="./12_Communities">Communities</a></strong></td><td style="text-align:left;">Communautés seniors, forums et plateformes de simulation</td><td style="text-align:center;">37</td><td style="text-align:left;"><a href="./12_Communities"><code>12_Communities.md</code></a></td></tr><tr><td style="text-align:center;">12</td><td style="text-align:left;"><strong><a href="./13_Companies_Hiring">Companies Hiring</a></strong></td><td style="text-align:left;">Niveau d&#39;évaluation de conception et style d&#39;entretien</td><td style="text-align:center;">67</td><td style="text-align:left;"><a href="./13_Companies_Hiring"><code>13_Companies_Hiring.md</code></a></td></tr><tr><td style="text-align:center;">13</td><td style="text-align:left;"><strong><a href="./14_Lets_Code_Resources">Lets Code Resources</a></strong></td><td style="text-align:left;">Outils d&#39;IA pour CV, préparation et communauté</td><td style="text-align:center;">34</td><td style="text-align:left;"><a href="./14_Lets_Code_Resources"><code>14_Lets_Code_Resources.md</code></a></td></tr><tr><td style="text-align:center;"></td><td style="text-align:left;"><strong>TOTAL RESSOURCES</strong></td><td style="text-align:left;"></td><td style="text-align:center;"><strong>585+</strong></td><td style="text-align:left;"></td></tr></tbody></table>',20)])])}const p=t(l,[["render",r]]);export{f as __pageData,p as default};
